        len1 = len(s1)
        len2 = len(s2)

        maxdist = len1 + len2
        d[-1, -1] = maxdist

        # matrix
        for i in range(len(s1) + 1):
            d[i, -1] = maxdist
            d[i, 0] = i
        for j in range(len(s2) + 1):
            d[-1, j] = maxdist
            d[0, j] = j

        for i, cs1 in enumerate(s1, start=1):
            db = 0
            for j, cs2 in enumerate(s2, start=1):
