                j1 = db
                if self.test_func(cs1, cs2):
                    cost = 0
                    db = j
                else:
                    cost = 1

                d[i, j] = min(
                    d[i - 1, j - 1] + cost,     # substitution
                    d[i, j - 1] + 1,            # insertion
                    d[i - 1, j] + 1,            # deletion
                    d[i1 - 1, j1 - 1] + (i - i1) - 1 + (j - j1),  # transposition
                )
